    const RAW_RULES = [{"folder":"australia","pattern":"^(?:AS/NZS|AS NZS|AS-NZS|AS\\s+\\d)","fallback":"/pages/standards/australia/index.html"},{"folder":"bsi","pattern":"^(?:BSI\\b|BS\\b)","fallback":"/pages/standard-products/bs.html"},{"folder":"din","pattern":"^DIN\\b","fallback":"/pages/standard-products/din.html"},{"folder":"iso","pattern":"^ISO\\b","fallback":"/pages/standard-products/iso.html"},{"folder":"asme","pattern":"^ASME\\b","fallback":"/pages/standard-products/asme.html"},{"folder":"ansi-asme-astm-ifi-sae","pattern":"^ANSI\\b","fallback":"/pages/standard-products/ansi.html"},{"folder":"astm","pattern":"^ASTM\\b","fallback":"/pages/standards/astm/index.html"},{"folder":"en","pattern":"^(?:CEN\\b|EN\\b)","fallback":"/pages/standard-products/cen.html"},{"folder":"dast","pattern":"^DAST\\b","fallback":"/pages/standards/dast/index.html"},{"folder":"gost","pattern":"^GOST\\b","fallback":"/pages/standard-products/gost.html"},{"folder":"is","pattern":"^IS\\b","fallback":"/pages/standard-products/is.html"},{"folder":"jis","pattern":"^JIS\\b","fallback":"/pages/standard-products/jis.html"},{"folder":"mil-ms-fed","pattern":"^(?:MIL\\b|MS\\b|FED\\b)","fallback":"/pages/standards/mil-ms-fed/index.html"},{"folder":"aia-nas","pattern":"^NAS\\b","fallback":"/pages/standards/aia-nas/index.html"},{"folder":"pn","pattern":"^PN\\b","fallback":"/pages/standard-products/pn.html"},{"folder":"uni","pattern":"^UNI\\b","fallback":"/pages/standard-products/uni.html"},{"folder":"csn","pattern":"^(?:CSN\\b|\u010cSN\\b)","fallback":"/pages/standard-products/csn.html"},{"folder":"sfs","pattern":"^SFS\\b","fallback":"/pages/standards/sfs/index.html"},{"folder":"sn-snv","pattern":"^(?:SN\\b|SNV\\b)","fallback":"/pages/standards/sn-snv/index.html"},{"folder":"sae","pattern":"^SAE\\b","fallback":"/pages/standards/sae/index.html"},{"folder":"une","pattern":"^UNE\\b","fallback":"/pages/standards/une/index.html"},{"folder":"nen","pattern":"^NEN\\b","fallback":"/pages/standards/nen/index.html"},{"folder":"nf","pattern":"^(?:NF\\b|AFNOR\\b)","fallback":"/pages/standards/nf/index.html"},{"folder":"gso","pattern":"^GSO\\b","fallback":"/pages/standards/gso/index.html"},{"folder":"ds","pattern":"^DS\\b","fallback":"/pages/standards/ds/index.html"},{"folder":"bds","pattern":"^BDS\\b","fallback":"/pages/standards/bds/index.html"}];

    const RULES = RAW_RULES.map(rule => ({
        ...rule,
        regex: new RegExp(rule.pattern, "i")
    }));

    function canonicalDesignation(value) {
        return String(value || "")
            .trim()
            .replace(/\s+\([^()]*[A-Za-z][^()]*\)\s*$/g, "")
            .replace(/\s+[—–]\s+.*$/g, "")
            .replace(/\s+-\s+.*$/g, "")
            .replace(/\s+/g, " ")
            .trim();
    }

    function slugify(value) {
        return canonicalDesignation(value)
            .toLowerCase()
            .replace(/&/g, " and ")
            .replace(/\+/g, " plus ")
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/^-+|-+$/g, "");
    }

    function detectAuthority(value) {
        const text = canonicalDesignation(value).toUpperCase();
        return RULES.find(rule => rule.regex.test(text)) || null;
    }

    function fallbackRoute(rule, standard) {
        const base = rule && rule.fallback
            ? rule.fallback
            : "/pages/products/standard-products.html";
        const separator = base.includes("?") ? "&" : "?";
        return `${base}${separator}standard=${
            encodeURIComponent(canonicalDesignation(standard))
        }`;
    }

    function resolve(standard) {
        const original = String(standard || "").trim();
        const clean = canonicalDesignation(original);

        if (!clean) {
            return "/pages/products/standard-products.html";
        }

        const rule = detectAuthority(clean);
        const slug = slugify(clean);

        if (rule && slug) {
            const route = (ROUTES[rule.folder] || {})[slug];
            if (route) return route;
            return fallbackRoute(rule, clean);
        }

        return `/pages/products/standard-products.html?standard=${
            encodeURIComponent(clean)
        }`;
    }

    window.PMEWStandardRouteResolver = Object.freeze({
        resolve,
        slugify,
        detectAuthority,
        canonicalDesignation
    });
